namespace gui_forms {

// GroupBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/group_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Whether an ampersand in the caption marks the access key (UseMnemonic); the access key moves the focus to the group's first focusable child.
template <typename Declaring>
struct GroupBoxUseMnemonicCapability {
    PropertyCell<bool, GroupBoxUseMnemonicCapability<Declaring>> use_mnemonic{true};

    static void assign(GroupBoxUseMnemonicCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.use_mnemonic), incoming);
        if (!capability.use_mnemonic.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.use_mnemonic));
    }
};

// Every GroupBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct GroupBoxCapabilities : public TextCapability<Declaring>,
                              public FontCapability<Declaring>,
                              public GroupBoxUseMnemonicCapability<Declaring> {
    GroupBoxCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::control, 12.0, 600, false, 0.24}) {}
};

} // namespace gui_forms
